  6	public class HuffmanCoding {
  7	    private static final String SINGLE_SYMBOL_CODE = "0";
  8	    private static final Comparator<Node> NODE_ORDER =
  9	            Comparator.comparingInt((Node node) -> node.frequency)
 10	                    .thenComparingInt(node -> node.order);
 11	
 12	    private static final class Node {
 13	        private final int frequency;
 14	        private final int order;
 15	        private final Node left;
 16	        private final Node right;
 17	
 18	        private Node(int frequency, int order) {
 19	            this(frequency, order, null, null);
 20	        }
 21	
 22	        private Node(Node left, Node right) {
 23	            this(left.frequency + right.frequency, Math.min(left.order, right.order), left, right);
 24	        }
