 26	        private Node(int frequency, int order, Node left, Node right) {
 27	            this.frequency = frequency;
 28	            this.order = order;
 29	            this.left = left;
 30	            this.right = right;
 31	        }
 32	
 33	        private boolean isLeaf() {
 34	            return left == null && right == null;
 35	        }
 36	    }
