 38	    static ArrayList<String> huffmanCodes(String symbols, int[] frequencies) {
 39	        validateInputs(symbols, frequencies);
 40	        if (symbols.isEmpty()) {
 41	            return new ArrayList<>();
 42	        }
 43	
 44	        PriorityQueue<Node> queue = buildLeafQueue(frequencies);
 45	        Node root = buildTree(queue);
 46	        return buildCodes(root);
 47	    }
