 49	    private static void validateInputs(String symbols, int[] frequencies) {
 50	        if (symbols == null) {
 51	            throw new IllegalArgumentException("symbols must not be null");
 52	        }
 53	        if (frequencies == null) {
 54	            throw new IllegalArgumentException("frequencies must not be null");
 55	        }
 56	        if (symbols.length() != frequencies.length) {
 57	            throw new IllegalArgumentException("symbols and frequencies must be the same length");
 58	        }
 59	    }
