 61	    private static PriorityQueue<Node> buildLeafQueue(int[] frequencies) {
 62	        PriorityQueue<Node> queue = new PriorityQueue<>(NODE_ORDER);
 63	        for (int i = 0; i < frequencies.length; i++) {
 64	            queue.add(new Node(frequencies[i], i));
 65	        }
 66	        return queue;
 67	    }
