 69	    private static Node buildTree(PriorityQueue<Node> queue) {
 70	        while (queue.size() > 1) {
 71	            Node left = queue.poll();
 72	            Node right = queue.poll();
 73	            queue.add(new Node(left, right));
 74	        }
 75	        return queue.peek();
 76	    }
